BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_RSOT_CANONICAL_OBJECT (ID VARCHAR2(36 CHAR) PRIMARY KEY, OBJECT_TYPE VARCHAR2(160 CHAR) NOT NULL, VERSION NUMBER(19) NOT NULL, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, SCHEMA_VERSION VARCHAR2(64 CHAR) NOT NULL, STATUS VARCHAR2(16 CHAR) NOT NULL, STATUS_REASON VARCHAR2(500 CHAR), EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL, EFFECTIVE_UNTIL TIMESTAMP(6) WITH TIME ZONE, ARCHIVED_AT TIMESTAMP(6) WITH TIME ZONE, ARCHIVED_BY VARCHAR2(36 CHAR), CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT CK_INX_RSOT_OBJ_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')), CONSTRAINT CK_INX_RSOT_OBJ_VERSION CHECK (VERSION>=1), CONSTRAINT CK_INX_RSOT_OBJ_STATUS CHECK (STATUS IN (''PROPOSED'',''VALIDATED'',''RECONCILED'',''DEPRECATED'',''ARCHIVED'')), CONSTRAINT CK_INX_RSOT_OBJ_PERIOD CHECK (EFFECTIVE_UNTIL IS NULL OR EFFECTIVE_UNTIL>EFFECTIVE_FROM), CONSTRAINT CK_INX_RSOT_OBJ_ARCH_PAIR CHECK ((ARCHIVED_AT IS NULL AND ARCHIVED_BY IS NULL) OR (ARCHIVED_AT IS NOT NULL AND ARCHIVED_BY IS NOT NULL)), CONSTRAINT CK_INX_RSOT_OBJ_ARCHIVED CHECK (STATUS<>''ARCHIVED'' OR ARCHIVED_AT IS NOT NULL), CONSTRAINT CK_INX_RSOT_OBJ_TIME CHECK (UPDATED_AT>=CREATED_AT AND EFFECTIVE_FROM>=CREATED_AT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_RSOT_OBJ_SCOPE ON INFRANEXUM_RSOT_CANONICAL_OBJECT(ORGANIZATION_ID,OBJECT_TYPE,STATUS,UPDATED_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_RSOT_ATTRIBUTE_AUTHORITY_POLICY (ID VARCHAR2(36 CHAR) PRIMARY KEY, OBJECT_TYPE VARCHAR2(160 CHAR) NOT NULL, ATTRIBUTE_PATH VARCHAR2(256 CHAR) NOT NULL, AUTHORITY_CONTEXT VARCHAR2(32 CHAR) NOT NULL, SOURCE_PRIORITY VARCHAR2(1000 CHAR) NOT NULL, EFFECTIVE_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL, EFFECTIVE_UNTIL TIMESTAMP(6) WITH TIME ZONE, POLICY_VERSION VARCHAR2(64 CHAR) NOT NULL, APPROVAL_REF VARCHAR2(200 CHAR) NOT NULL, CONSTRAINT UQ_INX_RSOT_AUTH_POLICY UNIQUE(OBJECT_TYPE,ATTRIBUTE_PATH,POLICY_VERSION), CONSTRAINT CK_INX_RSOT_AUTH_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')), CONSTRAINT CK_INX_RSOT_AUTH_CONTEXT CHECK (AUTHORITY_CONTEXT IN (''ORGANIZATION'',''IAM'',''RSOT'',''DISCOVERY'',''DCIM'',''DDI'',''ITAM'',''CORE_CAPABILITIES'',''GOVERNANCE_RSOT'')), CONSTRAINT CK_INX_RSOT_AUTH_PERIOD CHECK (EFFECTIVE_UNTIL IS NULL OR EFFECTIVE_UNTIL>EFFECTIVE_FROM), CONSTRAINT CK_INX_RSOT_AUTH_GLOBAL CHECK (OBJECT_TYPE NOT IN (''*'',''.*'') AND ATTRIBUTE_PATH NOT IN (''*'',''.*'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_RSOT_AUTH_LOOKUP ON INFRANEXUM_RSOT_ATTRIBUTE_AUTHORITY_POLICY(OBJECT_TYPE,ATTRIBUTE_PATH,EFFECTIVE_FROM,EFFECTIVE_UNTIL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_RSOT_AUTHORITY_MATRIX (POSITION_NO NUMBER(3) PRIMARY KEY, INFORMATION_TEXT VARCHAR2(300 CHAR) NOT NULL, AUTHORITY_NAME VARCHAR2(80 CHAR) NOT NULL, RSOT_CONTRIBUTION VARCHAR2(300 CHAR) NOT NULL, CONFLICT_STRATEGY VARCHAR2(300 CHAR) NOT NULL, MATRIX_VERSION VARCHAR2(64 CHAR) NOT NULL, CONSTRAINT CK_INX_RSOT_MATRIX_POS CHECK (POSITION_NO BETWEEN 1 AND 9))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_RSOT_CONTEXT_RELATIONSHIP (POSITION_NO NUMBER(3) PRIMARY KEY, PROVIDER_NAME VARCHAR2(100 CHAR) NOT NULL, CONTRIBUTION VARCHAR2(300 CHAR) NOT NULL, DIRECT_STORAGE_WRITE_ALLOWED NUMBER(1) DEFAULT 0 NOT NULL, CONSTRAINT CK_INX_RSOT_CONTEXT_POS CHECK (POSITION_NO BETWEEN 1 AND 10), CONSTRAINT CK_INX_RSOT_CONTEXT_WRITE CHECK (DIRECT_STORAGE_WRITE_ALLOWED=0))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/

MERGE INTO INFRANEXUM_RSOT_AUTHORITY_MATRIX t USING (SELECT 1 p,'Organisation, subdivision' i,'Organisation' a,'référence, scope, snapshot d’affichage' r,'l’autorité Organisation prévaut' c FROM dual UNION ALL SELECT 2,'Identité utilisateur et groupes','IAM','référence d’acteur, audit, ownership','l’autorité IAM prévaut' FROM dual UNION ALL SELECT 3,'Identité canonique d’un actif','RSOT','création, fusion, séparation, alias','workflow RSOT' FROM dual UNION ALL SELECT 4,'Observation brute','Discovery','association et provenance','observation immuable, pas d’écrasement' FROM dual UNION ALL SELECT 5,'Localisation physique','DCIM','consolidation sur l’actif','conflit remonté à DCIM/RSOT' FROM dual UNION ALL SELECT 6,'Adresse IP, préfixe, DNS, DHCP','DDI','relation canonique et recherche','DDI prévaut' FROM dual UNION ALL SELECT 7,'Contrat, garantie, licence patrimoniale','ITAM','référence et statut consolidé','ITAM prévaut' FROM dual UNION ALL SELECT 8,'Profil d’installation, quota, capability','Core Capabilities','lecture pour décisions','Core prévaut' FROM dual UNION ALL SELECT 9,'Politique de qualité','Governance/RSOT','exécution et preuve','version active approuvée' FROM dual) s ON (t.POSITION_NO=s.p) WHEN MATCHED THEN UPDATE SET t.INFORMATION_TEXT=s.i,t.AUTHORITY_NAME=s.a,t.RSOT_CONTRIBUTION=s.r,t.CONFLICT_STRATEGY=s.c,t.MATRIX_VERSION='2.0.0-draft.21' WHEN NOT MATCHED THEN INSERT(POSITION_NO,INFORMATION_TEXT,AUTHORITY_NAME,RSOT_CONTRIBUTION,CONFLICT_STRATEGY,MATRIX_VERSION) VALUES(s.p,s.i,s.a,s.r,s.c,'2.0.0-draft.21');

MERGE INTO INFRANEXUM_RSOT_CONTEXT_RELATIONSHIP t USING (SELECT 1 p,'Organization' n,'scope et identifiants d’organisation' c FROM dual UNION ALL SELECT 2,'IAM','acteurs et décisions d’accès' FROM dual UNION ALL SELECT 3,'Discovery','observations et preuves immuables' FROM dual UNION ALL SELECT 4,'DDI','changements dont DDI est autorité' FROM dual UNION ALL SELECT 5,'DCIM','changements dont DCIM est autorité' FROM dual UNION ALL SELECT 6,'ITAM','changements dont ITAM est autorité' FROM dual UNION ALL SELECT 7,'Governance','approbation des politiques selon le workflow défini' FROM dual UNION ALL SELECT 8,'Core Audit','réception des événements d’audit' FROM dual UNION ALL SELECT 9,'Core Contracts/Compatibility','registre de schémas' FROM dual UNION ALL SELECT 10,'Core Capabilities','capabilities et quotas' FROM dual) s ON (t.POSITION_NO=s.p) WHEN MATCHED THEN UPDATE SET t.PROVIDER_NAME=s.n,t.CONTRIBUTION=s.c,t.DIRECT_STORAGE_WRITE_ALLOWED=0 WHEN NOT MATCHED THEN INSERT(POSITION_NO,PROVIDER_NAME,CONTRIBUTION,DIRECT_STORAGE_WRITE_ALLOWED) VALUES(s.p,s.n,s.c,0);
